## 📄 **2. `acp_orchestrator.py` – ACP Orchestrator with Feedback and Dynamic Assignment**

```python
from agents import (
    DomainSpecialistAgent,
    ExpertModelAgent,
    GeneralistModelAgent,
    CrosscheckerAgent,
    UserInterfaceLayerAgent,
    PostEvaluatorAgent,
    RoleRegistry
)

class ACPOrchestrator:
    def __init__(self):
        self.role_registry = RoleRegistry()
        self.agents = {
            "Domain Specialist": DomainSpecialistAgent(),
            "Expert Model": ExpertModelAgent(),
            "Generalist Model": GeneralistModelAgent(),
            "Cross-checker": CrosscheckerAgent(),
            "User Interface Layer": UserInterfaceLayerAgent(),
            "Post-Evaluator": PostEvaluatorAgent()
        }

    def run_pipeline(self, input_text, user_profile="general", domain=None):
        pipeline_steps = {}

        # Dynamic role assignment
        model_name = self.role_registry.get_best_model_for_stage("Domain Specialist", domain)
        pipeline_steps["domain"] = self.agents[model_name].process(input_text)

        model_name = self.role_registry.get_best_model_for_stage("Expert", domain)
        pipeline_steps["expert"] = self.agents[model_name].process(pipeline_steps["domain"])

        model_name = self.role_registry.get_best_model_for_stage("Generalist", domain)
        pipeline_steps["general"] = self.agents[model_name].process(pipeline_steps["expert"])

        model_name = self.role_registry.get_best_model_for_stage("Cross-checker", domain)
        pipeline_steps["validated"] = self.agents[model_name].validate(pipeline_steps["general"])

        model_name = self.role_registry.get_best_model_for_stage("User Interface", domain)
        pipeline_steps["user_interface"] = self.agents[model_name].adapt(pipeline_steps["validated"], user_profile)

        final_output = pipeline_steps["user_interface"]

        return {
            "output": final_output,
            "steps": pipeline_steps
        }

    def handle_feedback(self, feedback, pipeline_steps):
        if "needs_clarification" in feedback:
            return self.agents["Generalist Model"].process(pipeline_steps["expert"])
        elif "missing_details" in feedback:
            return self.agents["Expert Model"].process(pipeline_steps["domain"])
        elif "incorrect_conclusion" in feedback:
            return self.agents["Cross-checker"].validate(pipeline_steps["general"], correction=True)
        else:
            return pipeline_steps["output"]

    def post_evaluate(self, final_output, user_feedback):
        return self.agents["Post-Evaluator"].analyze(final_output, user_feedback)
```

